//! C-alignment regression tests (step H2: insert-side page splitting, cell placement and page allocation).
//! GENERATED by target/perf-work/h2/gen_tests.py: every expected value is what C SQLite 3.54.1 produces — size and
//! FNV-1a hash of the database file C writes for the statements, and (last test) the cell count of every page of an
//! index C builds through a `BTREE_BULKLOAD` cursor. Each file case fails with the insert code of step H1b (own split
//! code, clean page layout); nothing here depends on files outside the repository.
use crate::Connection;

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h = (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h2-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

fn assert_file_is_what_c_writes(name: &str, stmts: &[&str], c_size: usize, c_hash: u64) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        conn.query(sql, &[])
            .unwrap_or_else(|e| panic!("{name}: {sql}: {e:?}"));
    }
    assert!(conn.try_close().is_ok());
    let bytes = std::fs::read(&db.0).unwrap();
    assert_eq!(bytes.len(), c_size, "{name}: file size");
    assert_eq!(fnv1a(&bytes), c_hash, "{name}: file content differs from C");
}

/// Random-order inserts into a table tree (class B4): an overfull leaf in the middle of the tree is balanced with its two neighbours (`balance_nonroot`, left-biased packing, pages numbered in ascending order) instead of being split in two.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_table_random_inserts_redistribute_over_three_siblings_1024() {
    assert_file_is_what_c_writes(
        "table_random_inserts_redistribute_over_three_siblings_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<1500) INSERT INTO t SELECT (x*7919)%4507+1, printf('%0*d', 20 + (x*7919)%90, x) FROM c;",
        ],
        133120,
        0x982aefa3711740f8,
    );
}

/// Index leaf and root splits (class B5): distribution by bytes with the right-to-left evening loop, `balance_deeper` for the root, sibling page numbers as C assigns them.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_index_split_points_and_root_split_512() {
    assert_file_is_what_c_writes(
        "index_split_points_and_root_split_512",
        &[
            "PRAGMA page_size=512;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, k TEXT);",
            "CREATE INDEX tk ON t(k);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<900) INSERT INTO t SELECT x, printf('%0*d', 6 + (x*31)%40, (x*7919)%100003) FROM c;",
        ],
        69632,
        0xee8baa4bc117c2ed,
    );
}

/// Sequential appends past one interior page (classes B6, B14): `balance_quick` for the right-most leaf, interior pages split by `balance_nonroot` (84-88% full in C, 50% before this step).
/// The database file is byte-identical to the one C writes.
#[test]
fn file_table_interior_pages_packed_on_append_512() {
    assert_file_is_what_c_writes(
        "table_interior_pages_packed_on_append_512",
        &[
            "PRAGMA page_size=512;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<6000) INSERT INTO t SELECT x, printf('%020d', x) FROM c;",
        ],
        175104,
        0x297fe329ea7bcdf5,
    );
}

/// In-page placement (class B10): deletes leave freeblocks, growing / shrinking UPDATEs drop and re-insert cells, new cells take the first freeblock that fits (`allocateSpace` / `pageFindSlot`), fragments are counted, `defragmentPage` runs only when the gap is too small.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_growing_updates_and_freeblock_reuse_4096() {
    assert_file_is_what_c_writes(
        "growing_updates_and_freeblock_reuse_4096",
        &[
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT, b TEXT);",
            "CREATE INDEX ta ON t(a);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<1200) INSERT INTO t SELECT x, printf('%0*d', 8 + (x*7)%50, x), printf('%.*c', (x*13)%120, 'b') FROM c;",
            "DELETE FROM t WHERE id%3=0;",
            "UPDATE t SET b=b||'grown-grown-grown-grown' WHERE id%5=0;",
            "UPDATE t SET b=substr(b,1,length(b)/2) WHERE id%7=0;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<500) INSERT INTO t SELECT 5000+x, printf('%0*d', 8 + (x*11)%50, x), printf('%.*c', (x*17)%160, 'c') FROM c;",
            "UPDATE t SET a=a||'x' WHERE id%4=1;",
            "DELETE FROM t WHERE id%11=2;",
        ],
        258048,
        0x6ffd3eb2f8b60d7b,
    );
}

/// Rows with overflow chains: same-size UPDATE overwrites the chain in place (`btreeOverwriteCell`), a growing row gets a new chain before the old one is freed (`fillInCell` then `BTREE_CLEAR_CELL`), the free list is reused with C's `nearby` hints.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_overflow_rows_overwrite_replace_and_grow_1024() {
    assert_file_is_what_c_writes(
        "overflow_rows_overwrite_replace_and_grow_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a BLOB, n INT);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<90) INSERT INTO t SELECT x, zeroblob(900+x*37), x FROM c;",
            "UPDATE t SET n=n+1000 WHERE id%2=0;",
            "UPDATE t SET a=zeroblob(2500+id*11) WHERE id%3=0;",
            "UPDATE t SET a=zeroblob(id) WHERE id%3=1;",
            "DELETE FROM t WHERE id%10=5;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO t SELECT 200+x, zeroblob(700+x*90), x FROM c;",
        ],
        290816,
        0x2d7d46195e317d71,
    );
}

/// REPLACE on a rowid conflict of a table without any index: C's cursor was only positioned by OP_NotExists (cell not parsed), so a record of the same size is not overwritten in place; the new overflow chain is allocated before the old one is freed.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_replace_on_table_without_index_builds_new_chain_1024() {
    assert_file_is_what_c_writes(
        "replace_on_table_without_index_builds_new_chain_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a BLOB);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO t SELECT x, zeroblob(1500+x*20) FROM c;",
            "REPLACE INTO t VALUES(2, zeroblob(1540));",
            "REPLACE INTO t VALUES(5, zeroblob(1600));",
            "REPLACE INTO t VALUES(8, zeroblob(1660));",
            "REPLACE INTO t VALUES(11, zeroblob(1720));",
            "REPLACE INTO t VALUES(14, zeroblob(1780));",
            "REPLACE INTO t VALUES(17, zeroblob(1840));",
            "REPLACE INTO t VALUES(20, zeroblob(1900));",
            "REPLACE INTO t VALUES(23, zeroblob(1960));",
            "REPLACE INTO t VALUES(26, zeroblob(2020));",
            "REPLACE INTO t VALUES(29, zeroblob(2080));",
            "REPLACE INTO t VALUES(32, zeroblob(2140));",
            "REPLACE INTO t VALUES(35, zeroblob(2200));",
            "REPLACE INTO t VALUES(38, zeroblob(2260));",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<10) INSERT INTO t SELECT 100+x, zeroblob(3000) FROM c;",
        ],
        117760,
        0xe1141c2f1874c66a,
    );
}

/// Two-pass UPDATE (sub-select in WHERE) assigning every column from constants: C's cursor is positioned by OP_NotExists and never parses the old cell, so even a record of the same size is replaced through fillInCell + BTREE_CLEAR_CELL (new overflow chain first); an UPDATE that reads a column of the old row overwrites in place.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_two_pass_update_that_reads_no_old_column_1024() {
    assert_file_is_what_c_writes(
        "two_pass_update_that_reads_no_old_column_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a BLOB, n INT);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<60) INSERT INTO t SELECT x, zeroblob(900+x*37), x FROM c;",
            "DELETE FROM t WHERE id%7=0;",
            "UPDATE t SET a=zeroblob(900+11*37), n=5 WHERE id IN (SELECT 11);",
            "UPDATE t SET a=zeroblob(2000), n=7 WHERE id IN (SELECT id FROM t WHERE id%5=0);",
            "UPDATE t SET a=zeroblob(2000), n=7 WHERE id IN (SELECT id FROM t WHERE id%5=0);",
            "UPDATE t SET n=9 WHERE id IN (SELECT id FROM t WHERE id%4=0);",
            "UPDATE t SET a=zeroblob(length(a)), n=1 WHERE id IN (SELECT id FROM t WHERE id%3=0);",
        ],
        135168,
        0xcb4a0fc137644c01,
    );
}

