/// Auto_vacuum=FULL: pointer-map entries of overflow chains, of pages allocated by balance_quick / balance_nonroot / balance_deeper and of cells that move between siblings.
/// The database file is byte-identical to the one C writes.
#[test]
fn file_auto_vacuum_inserts_with_overflow_and_index_1024() {
    assert_file_is_what_c_writes(
        "auto_vacuum_inserts_with_overflow_and_index_1024",
        &[
            "PRAGMA page_size=1024;",
            "PRAGMA auto_vacuum=1;",
            "CREATE TABLE t(id INTEGER PRIMARY KEY, a TEXT, b BLOB);",
            "CREATE INDEX ta ON t(a);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<600) INSERT INTO t SELECT (x*7919)%1801+1, printf('%0*d', 8 + (x*7)%50, x), zeroblob((x*31)%700) FROM c;",
            "DELETE FROM t WHERE id%3=0;",
            "UPDATE t SET b=zeroblob(length(b)+400) WHERE id%5=0;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<200) INSERT INTO t SELECT 5000+x, printf('%0*d', 8 + (x*7)%50, x), zeroblob((x*37)%2500) FROM c;",
        ],
        605184,
        0x9a793a46c7f35ac7,
    );
}

