/// `(is_leaf, cell count)` of every page of the index tree at `root`, parents before children, children left to right
/// (the order of C's `dbstat ... ORDER BY path`).
fn index_shape(bt: &mut sqliters_btree::Btree, pgno: u32, out: &mut Vec<(bool, usize)>) {
    let (leaf, n_cell, children) = {
        let d = bt.pager_mut().read_page(pgno).unwrap();
        let leaf = d[0] == 0x0a;
        let n_cell = usize::from(u16::from_be_bytes([d[3], d[4]]));
        let mut children = Vec::new();
        if !leaf {
            for i in 0..n_cell {
                let off = usize::from(u16::from_be_bytes([d[12 + 2 * i], d[13 + 2 * i]]));
                children.push(u32::from_be_bytes([
                    d[off],
                    d[off + 1],
                    d[off + 2],
                    d[off + 3],
                ]));
            }
            children.push(u32::from_be_bytes([d[8], d[9], d[10], d[11]]));
        }
        (leaf, n_cell, children)
    };
    out.push((leaf, n_cell));
    for c in children {
        index_shape(bt, c, out);
    }
}

/// `BTREE_BULKLOAD` (`balance_nonroot(bBulk=1)`): appending sorted keys through `Btree::insert_index_bulk` gives the
/// page-for-page shape of the index C builds with `CREATE INDEX` (sorter, then `OP_IdxInsert` appends through a cursor
/// opened with `OPFLAG_BULKCSR`): left siblings stay packed, only the right-most leaf is short.
